class Solution {
  public int sumSubseqWidths(int[] nums) {
    final long MOD = 1_000_000_007L;
    Arrays.sort(nums);
    int n = nums.length;
    long power = 1, answer = 0;
    // nums[i] is the maximum of 2^i subsequences and the minimum of 2^(n-1-i)
    long[] pow2 = new long[n];
    for (int i = 0; i < n; i++) {
      pow2[i] = power;
      power = power * 2 % MOD;
    }
    for (int i = 0; i < n; i++) {
      answer = (answer + nums[i] * ((pow2[i] - pow2[n - 1 - i] + MOD) % MOD)) % MOD;
    }
    return (int) answer;
  }
}
